import{_ as a,a0 as u,w as i,s as l,ao as d,I as r,x as o,a1 as t,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何在Ubuntu 14.04 / 15.04中設置IonCube Loaders | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu 14.04 / 15.04中設置IonCube Loaders | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu 14.04 / 15.04中設置IonCube Loaders | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu 14.04 / 15.04中設置IonCube Loaders | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20150921 How to Setup IonCube Loaders on Ubuntu 14.04 or 15.04","title":"如何在Ubuntu 14.04 / 15.04中設置IonCube Loaders","tag":"201510","desc":""},"relativePath":"201510/20150921 How to Setup IonCube Loaders on Ubuntu 14.04 or 15.04.md","filePath":"[post].md"}'),s={name:"201510/20150921 How to Setup IonCube Loaders on Ubuntu 14.04 or 15.04.md"};function b(c,e,h,m,P,x){const n=u("Link");return i(),l("div",null,[e[13]||(e[13]=d(`<h1 id="如何在ubuntu-14-04-15-04中設置ioncube-loaders" tabindex="-1">如何在Ubuntu 14.04 / 15.04中設置IonCube Loaders <a class="header-anchor" href="#如何在ubuntu-14-04-15-04中設置ioncube-loaders" aria-label="Permalink to “如何在Ubuntu 14.04 / 15.04中設置IonCube Loaders”">​</a></h1><p>IonCube Loaders是一個PHP中用於加解密的工具，並帶有加速頁面運行的功能。它也可以保護你的PHP代碼不會查看和運行在未授權的計算機上。要使用ionCube編碼、加密的PHP文件，需要在web服務器上安裝一個叫ionCube Loader的文件，並需要讓 PHP 可以訪問到，很多 PHP 應用都在用它。它可以在運行時讀取並執行編碼過後的代碼。PHP只需在‘php.ini’中添加一行就可以使用這個loader。</p><h3 id="前提條件" tabindex="-1">前提條件 <a class="header-anchor" href="#前提條件" aria-label="Permalink to “前提條件”">​</a></h3><p>在這篇文章中，我們將在Ubuntu14.04/15.04安裝Ioncube Loader ，以便它可以在所有PHP模式中使用。本教程的唯一要求就是你係統安裝了LEMP，並有“php.ini”文件。</p><h3 id="下載-ioncube-loader" tabindex="-1">下載 IonCube Loader <a class="header-anchor" href="#下載-ioncube-loader" aria-label="Permalink to “下載 IonCube Loader”">​</a></h3><p>根據你係統的架構是32位或者64位來下載最新的IonCube loader包。你可以用超級用户權限或者root用户運行下面的命令。</p><pre><code># wget http://downloads3.ioncube.com/loader_downloads/ioncube_loaders_lin_x86-64.tar.gz
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/download1.png" alt="download ioncube"></p><p>下載完成後用下面的命令解壓到“/usr/local/src/&quot;。</p><pre><code># tar -zxvf ioncube_loaders_lin_x86-64.tar.gz -C /usr/local/src/
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/2-extract.png" alt="extracting archive"></p><p>解壓完成後我們就可以看到所有提供的模組。但是我們只需要我們所安裝的PHP版本的對應模組。</p><p>要檢查PHP版本，你可以運行下面的命令來找出相應的模組。</p><pre><code># php -v
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/modules.png" alt="ioncube modules"></p><p>根據上面的命令我們知道我們安裝的是PHP 5.6.4，因此我們需要拷貝合適的模組到PHP模組目錄下。</p><p>首先我們在“/usr/local/”創建一個叫“ioncube”的目錄並複製所需的ioncube loader到這裏。</p><pre><code>root@ubuntu-15:/usr/local/src/ioncube# mkdir /usr/local/ioncube
root@ubuntu-15:/usr/local/src/ioncube# cp ioncube_loader_lin_5.6.so ioncube_loader_lin_5.6_ts.so /usr/local/ioncube/
</code></pre><h3 id="php-配置" tabindex="-1">PHP 配置 <a class="header-anchor" href="#php-配置" aria-label="Permalink to “PHP 配置”">​</a></h3><p>我們要在位於&quot;/etc/php5/cli/&quot;文件夾下的&quot;php.ini&quot;中加入如下的配置行並重啓web服務和php模組。</p><pre><code># vim /etc/php5/cli/php.ini
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/zend-extension.png" alt="ioncube zend extension"></p><p>此時我們安裝的是nginx，因此我們用下面的命令來重啓服務。</p><pre><code># service php5-fpm restart
# service nginx restart
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/web-services.png" alt="web services"></p><h3 id="測試-ioncube-loader" tabindex="-1">測試 IonCube Loader <a class="header-anchor" href="#測試-ioncube-loader" aria-label="Permalink to “測試 IonCube Loader”">​</a></h3><p>要為我們的網站測試ioncube loader。用下面的內容創建一個&quot;info.php&quot;文件並放在網站的web目錄下。</p><pre><code># vim /usr/share/nginx/html/info.php
</code></pre><p>加入phpinfo的腳本後重啓web服務後用域名或者ip地址訪問“info.php”。</p><p>你會在最下面的php模組信息裏看到下面這段。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/php-info.png" alt="php info"></p><p>在終端中運行下面的命令來驗證php版本並顯示PHP Loader已經啓用了。</p><pre><code># php -v
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/php-ioncube.png" alt="php ioncube loader"></p><p>上面的php版本輸出明顯地顯示了IonCube loader已經成功與PHP集成了。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>教程的最後你已經瞭解瞭如何在安裝有nginx的Ubuntu中安裝和配置ionCube Loader，如果你正在使用其他的web服務，這與其他服務沒有明顯的差別。因此安裝Loader是很簡單的，並且在大多數服務器上的安裝都不會有問題。然而並沒有一個所謂的“標準PHP安裝”，服務可以通過許多方式安裝，並啓用或者禁用功能。</p><p>如果你是在共享服務器上，那麼確保運行了ioncube-loader-helper.php腳本，並點擊鏈接來測試運行時安裝。如果安裝時你仍然遇到了問題，歡迎聯繫我們及給我們留下評論。</p><hr>`,39)),r("p",null,[e[1]||(e[1]=o("via: ",-1)),t(n,{href:"http://linoxide.com/ubuntu-how-to/setup-ioncube-loaders-ubuntu-14-04-15-04/"},{default:p(()=>[...e[0]||(e[0]=[o("http://linoxide.com/ubuntu-how-to/setup-ioncube-loaders-ubuntu-14-04-15-04/",-1)])]),_:1})]),r("p",null,[e[5]||(e[5]=o("作者：",-1)),t(n,{href:"http://linoxide.com/author/kashifs/"},{default:p(()=>[...e[2]||(e[2]=[o("Kashif Siddique",-1)])]),_:1}),e[6]||(e[6]=o(" 譯者：",-1)),t(n,{href:"https://github.com/geekpi"},{default:p(()=>[...e[3]||(e[3]=[o("geekpi",-1)])]),_:1}),e[7]||(e[7]=o(" 校對：",-1)),t(n,{href:"https://github.com/wxy"},{default:p(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),r("p",null,[e[10]||(e[10]=o("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原創編譯，",-1)),t(n,{href:"https://linux.cn/"},{default:p(()=>[...e[9]||(e[9]=[o("Linux中國",-1)])]),_:1}),e[12]||(e[12]=o(" 榮譽推出",-1))])])}const L=a(s,[["render",b]]);export{f as __pageData,L as default};
